/**
 * @fileoverview BurnBench evidence-export loader + presentation maps.
 *
 * Canonical data file: `website/public/data/bench.json` — regenerated by the
 * BurnBench pipeline (contract: recommendation-platform-contracts.md §3) and
 * served verbatim at `/data/bench.json`. Pages read it here at build time, so
 * every bench page is fully static and rebuilds pick up pipeline refreshes.
 *
 * The loader is deliberately shape-tolerant: the export's harness/model ids,
 * family scopes, and ranges evolve with the pipeline, so colors, logos,
 * monograms, and chart domains all fall back deterministically for ids the
 * site doesn't know yet.
 *
 * Presentation maps (brand colors, logo paths) live here, not in the JSON:
 * the pipeline owns numbers, the site owns how they look. Logos are the real
 * brand assets already served from `/brand/providers/` (contract §5b) —
 * never hotlinked, never re-hosted.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";

/* ---------- contract §3 types ---------- */

export interface BenchScope {
  family: string | null;
  language: string | null;
  platform: string | null;
}

export interface BenchModel {
  id: string;
  display: string;
  provider: string;
}

export interface BenchHarness {
  id: string;
  display: string;
}

export type BenchConfidence = "high" | "medium" | "low";
export type BenchEvidence = "measured" | "inferred";

export type BenchCostSource = "measured" | "derived" | "none";

export interface BenchStack {
  harness: string;
  model: string;
  config: string;
  scope: BenchScope;
  n: number;
  strict_rate: number;
  solution_rate: number;
  ci95: [number, number];
  cost_usd_median: number | null;
  cost_source: BenchCostSource;
  cost_input_usd_median: number | null;
  cost_output_usd_median: number | null;
  /** Amendment 12: standard-tier (non-contributor) equivalent for subsidized models. */
  cost_standard_usd_median: number | null;
  wall_seconds_median: number | null;
  tokens_median: number | null;
  arena_bt: number | null;
  confidence: BenchConfidence;
  evidence: BenchEvidence;
  /** Kimi-judge quality_mean (1-5 scale), n-weighted median of per-task
      medians for this scope slice. null when no trials were judged. */
  quality_mean: number | null;
  /** Number of judged trials backing quality_mean (0 when unjudged). */
  quality_n: number;
  /* ── graded scoring (docs/graded-scoring.md in the bench repo) ──────────
     A weighted 0-100 score plus a bronze/silver/gold ladder, emitted by
     converted tasks alongside the unchanged pass/fail verdict.

     Every field is optional on purpose: exports predating grading omit them,
     and an ungraded cell contributes nothing rather than zero — a task that
     has not been converted must never look like a task scored badly. */
  /** Median graded score (0-100) across this slice's graded cells. */
  score_median?: number | null;
  /** Number of graded cells behind score_median (0 when none). */
  score_n?: number;
  /** How far runs actually got: cell counts by highest fully-cleared tier.
      Exported as `score_tiers`; must match the export generator's field name
      exactly or the ladder silently renders zeros. */
  score_tiers?: {
    gold?: number;
    silver?: number;
    bronze?: number;
    none?: number;
  } | null;
}

export interface BenchFrontierPoint {
  harness: string;
  model: string;
  scope: BenchScope;
  solution_rate: number;
  cost_usd_median: number;
  wall_seconds_median: number;
}

export interface BenchArenaRating {
  harness: string;
  model: string;
  bt: number;
  ci95: [number, number];
  votes: number;
}

export interface BenchDoc {
  schema_version: number;
  generated_at_utc: string;
  source: {
    trees: string[];
    cells_measured: number;
    cells_excluded: number;
    runs_sha256: string;
  };
  models: BenchModel[];
  harnesses: BenchHarness[];
  stacks: BenchStack[];
  frontier: BenchFrontierPoint[];
  arena: { votes: number; ratings: BenchArenaRating[] };
}

/* ---------- build-time read (pages are static) ---------- */

const raw = readFileSync(join(process.cwd(), "public", "data", "bench.json"), "utf8");
export const BENCH: BenchDoc = JSON.parse(raw);

/**
 * **`source.cells_measured` is a TRIAL count, not a cell count.**
 *
 * The pipeline's field name is a misnomer the site must not repeat: the value
 * equals `evidence.global.n`, i.e. the sum of every measured cell's `n`, so it
 * counts individual runs. On the current export it is 3,070 — against 658
 * distinct (harness × model × task) cells (`TASK_CELLS`).
 *
 * Read this constant wherever the number is displayed, and label it *trials*.
 * `test/bench-data.test.ts` pins the identity, so if a future export ever
 * changes the field to mean what it says, the tests fail and the labels get
 * revisited instead of silently flipping meaning under the copy.
 */
export const TRIALS_MEASURED: number = BENCH.source.cells_measured;

/**
 * Trials the pipeline dropped (superseded reruns, invalid runs). Same caveat
 * as `TRIALS_MEASURED`: the export's `cells_excluded` name is the pipeline's,
 * and the unit is not independently verifiable from the published files — so
 * render it without asserting a noun ("368 excluded by policy"), never as
 * "368 cells".
 */
export const EXCLUDED_MEASURED: number = BENCH.source.cells_excluded;

